CREATE TABLE context_rights_approval (approval_id TEXT PRIMARY KEY,source_schema TEXT NOT NULL,approval_ref TEXT NOT NULL,receipt_sha256 TEXT NOT NULL CHECK(length(receipt_sha256)=64),message_ref TEXT,proposal_sha256 TEXT,package_sha256 TEXT,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_rights_original_source (approval_id TEXT NOT NULL REFERENCES context_rights_approval(approval_id),role TEXT NOT NULL,logical_path TEXT NOT NULL,expected_sha256 TEXT NOT NULL CHECK(length(expected_sha256)=64),original_source_id INTEGER NOT NULL REFERENCES source_file(source_id),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(approval_id,role),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_rights_transition (set_name TEXT NOT NULL CHECK(set_name IN ('titles','grants','holdings','existingTitleBindings')),old_id TEXT NOT NULL,original_value_sha256 TEXT NOT NULL CHECK(length(original_value_sha256)=64),disposition TEXT NOT NULL CHECK(disposition IN ('retained-current','retired-current','seoul-jurisdiction-only','approved-nonowning')),current_id TEXT,approval_id TEXT NOT NULL REFERENCES context_rights_approval(approval_id),source_ordinal INTEGER NOT NULL CHECK(source_ordinal>=0),original_source_id INTEGER NOT NULL,original_json_pointer TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(set_name,old_id),FOREIGN KEY(original_source_id,original_json_pointer) REFERENCES source_record(source_id,json_pointer),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_outside_retirement (set_name TEXT NOT NULL CHECK(set_name IN ('assignments','islandUnits')),unit_id TEXT NOT NULL,record_key TEXT NOT NULL UNIQUE,original_value_sha256 TEXT NOT NULL CHECK(length(original_value_sha256)=64),status TEXT NOT NULL CHECK(status='retired-current'),approval_ref TEXT NOT NULL,approval_id TEXT NOT NULL REFERENCES context_rights_approval(approval_id),original_source_id INTEGER NOT NULL,original_json_pointer TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(set_name,unit_id),FOREIGN KEY(original_source_id,original_json_pointer) REFERENCES source_record(source_id,json_pointer),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_feudal_title (title_id TEXT PRIMARY KEY,name TEXT NOT NULL,rank TEXT NOT NULL CHECK(rank IN ('barony','county','duchy','kingdom','empire')),holder_person_id TEXT NOT NULL REFERENCES person(person_id),polity_id TEXT NOT NULL,parent_title_id TEXT REFERENCES context_feudal_title(title_id) DEFERRABLE INITIALLY DEFERRED,geographic_title_id TEXT,geographic_parent_title_id TEXT,political_parent_title_id TEXT,personal_liege_person_id TEXT REFERENCES person(person_id),kind TEXT,direct_ownership INTEGER CHECK(direct_ownership IN (0,1)),basis TEXT NOT NULL,transition_set TEXT NOT NULL CHECK(transition_set='titles'),transition_old_id TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(transition_set,transition_old_id) REFERENCES context_rights_transition(set_name,old_id),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_feudal_jurisdiction (title_id TEXT NOT NULL REFERENCES context_feudal_title(title_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),admin_unit_id TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(title_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_feudal_grant (grant_id TEXT PRIMARY KEY,name_ko TEXT NOT NULL,name_en TEXT,holder_person_id TEXT NOT NULL REFERENCES person(person_id),liege_person_id TEXT REFERENCES person(person_id),polity_id TEXT NOT NULL,title_id TEXT NOT NULL REFERENCES context_feudal_title(title_id),geometry_source TEXT,territorial_scale TEXT,formal_title_rank TEXT,transition_set TEXT NOT NULL CHECK(transition_set='grants'),transition_old_id TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(transition_set,transition_old_id) REFERENCES context_rights_transition(set_name,old_id),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_feudal_grant_admin (grant_id TEXT NOT NULL REFERENCES context_feudal_grant(grant_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),admin_unit_id TEXT NOT NULL,admin_unit_name TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(grant_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_feudal_grant_component (grant_id TEXT NOT NULL REFERENCES context_feudal_grant(grant_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),admin_unit_id TEXT NOT NULL,component_index INTEGER NOT NULL CHECK(component_index>=0),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(grant_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_political_identity (identity_id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind='nonterritorial-political-identity'),rank TEXT NOT NULL,holder_person_id TEXT NOT NULL REFERENCES person(person_id),polity_id TEXT NOT NULL,political_parent_title_id TEXT,direct_ownership INTEGER NOT NULL CHECK(direct_ownership=0),transition_set TEXT NOT NULL CHECK(transition_set='titles'),transition_old_id TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(transition_set,transition_old_id) REFERENCES context_rights_transition(set_name,old_id),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_political_identity_liege (identity_id TEXT NOT NULL REFERENCES context_political_identity(identity_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),historical_holding_id TEXT NOT NULL,liege_person_id TEXT REFERENCES person(person_id),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(identity_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_holding_geographic_scope (holding_id TEXT PRIMARY KEY REFERENCES context_holding(holding_id),duchy_title_id TEXT NOT NULL,gu_ref TEXT NOT NULL,kingdom_geography_id TEXT NOT NULL,empire_geography_id TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_holding_scope_county (holding_id TEXT NOT NULL REFERENCES context_holding(holding_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),county_title_id TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(holding_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_holding_power (holding_id TEXT NOT NULL REFERENCES context_holding(holding_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),power TEXT NOT NULL CHECK(power IN ('receive-holding-change-notice','lodge-nonbinding-registry-objection')),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(holding_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_feudal_binding (holding_id TEXT PRIMARY KEY REFERENCES context_holding(holding_id),title_id TEXT NOT NULL REFERENCES context_feudal_title(title_id),liege_relationship_kind TEXT,basis TEXT,transition_set TEXT NOT NULL CHECK(transition_set='existingTitleBindings'),transition_old_id TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(transition_set,transition_old_id) REFERENCES context_rights_transition(set_name,old_id),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_office_history (person_id TEXT PRIMARY KEY REFERENCES context_office_appointment(person_id),polity_id TEXT NOT NULL,position_ko TEXT NOT NULL,position_en TEXT,rank_ko TEXT NOT NULL,rank_en TEXT,common_tier TEXT NOT NULL CHECK(common_tier GLOB 'T[1-5]'),approval_ref TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_office_evidence (person_id TEXT NOT NULL REFERENCES context_office_appointment(person_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),reference_path TEXT NOT NULL,reference_pointer TEXT NOT NULL,evidence_kind TEXT NOT NULL,reference_source_id INTEGER NOT NULL,reference_json_pointer TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(person_id,ordinal),FOREIGN KEY(reference_source_id,reference_json_pointer) REFERENCES source_record(source_id,json_pointer),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_court (court_id TEXT PRIMARY KEY,owner_person_id TEXT NOT NULL REFERENCES person(person_id),polity_id TEXT NOT NULL,source_schema TEXT NOT NULL,effective_year INTEGER NOT NULL,approval_ref TEXT NOT NULL,catalog_status TEXT NOT NULL CHECK(catalog_status='current-catalog-input'),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_relation_contract (contract_id TEXT PRIMARY KEY,court_id_contract TEXT NOT NULL,source_ref_path TEXT NOT NULL,source_ref_anchor TEXT NOT NULL,source_schema TEXT NOT NULL,effective_year INTEGER NOT NULL,approval_ref TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_direct_retainer (person_id TEXT PRIMARY KEY REFERENCES person(person_id),liege_person_id TEXT NOT NULL REFERENCES person(person_id),court_id TEXT NOT NULL REFERENCES context_court(court_id),source_row INTEGER NOT NULL CHECK(source_row>=0),source_schema TEXT NOT NULL,effective_year INTEGER NOT NULL,approval_ref TEXT NOT NULL,catalog_status TEXT NOT NULL CHECK(catalog_status='current-catalog-input'),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer),CHECK(person_id<>liege_person_id)) STRICT;
CREATE TABLE context_owner_liege (person_id TEXT PRIMARY KEY REFERENCES person(person_id),liege_person_id TEXT NOT NULL REFERENCES person(person_id),relation_kind TEXT NOT NULL,owner_term TEXT NOT NULL,source_schema TEXT NOT NULL,effective_year INTEGER NOT NULL,approval_ref TEXT NOT NULL,catalog_status TEXT NOT NULL CHECK(catalog_status='current-catalog-input'),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer),CHECK(person_id<>liege_person_id)) STRICT;
CREATE TABLE context_owner_liege_source_basis (ordinal INTEGER PRIMARY KEY CHECK(ordinal>=0),source_ref_path TEXT NOT NULL,source_ref_anchor TEXT NOT NULL,source_quote TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_court_membership (person_id TEXT PRIMARY KEY REFERENCES person(person_id),court_id TEXT NOT NULL REFERENCES context_court(court_id),approval_ref TEXT NOT NULL,source_schema TEXT NOT NULL,effective_year INTEGER NOT NULL,catalog_status TEXT NOT NULL CHECK(catalog_status='current-catalog-input'),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_court_approval (court_id TEXT PRIMARY KEY REFERENCES context_court(court_id),approval_ref TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_organization (organization_id TEXT PRIMARY KEY,name TEXT NOT NULL,polity_id TEXT,source_anchor TEXT NOT NULL,catalog_status TEXT NOT NULL CHECK(catalog_status='current-catalog-input'),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_event_link (event_id TEXT NOT NULL,person_id TEXT NOT NULL REFERENCES person(person_id),organization_id TEXT REFERENCES context_organization(organization_id),catalog_status TEXT NOT NULL CHECK(catalog_status='current-catalog-input'),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(event_id,person_id),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_holding (holding_id TEXT PRIMARY KEY,name_ko TEXT NOT NULL,name_en TEXT,holder_person_id TEXT NOT NULL REFERENCES person(person_id),direct_liege_person_id TEXT REFERENCES person(person_id),polity_id TEXT NOT NULL,territorial_scale TEXT,formal_title_rank TEXT,geometry_source TEXT,designation_ko TEXT,designation_en TEXT,parent_geography TEXT,whole_seoul_control INTEGER CHECK(whole_seoul_control IN (0,1)),current_validity TEXT NOT NULL CHECK(current_validity IN ('current_seoul_evidenced','current_seoul_nonowning','superseded_outside_seoul','unresolved')),canon_status TEXT NOT NULL CHECK(canon_status IN ('current_seoul_evidenced','current_seoul_nonowning','superseded_outside_seoul','unresolved')),authority_date TEXT,authority_ref TEXT NOT NULL,source_schema TEXT NOT NULL,opening_year INTEGER NOT NULL,kind TEXT,direct_ownership INTEGER CHECK(direct_ownership IN (0,1)),title_id TEXT REFERENCES context_feudal_title(title_id),liege_relationship_kind TEXT,capability_package_id TEXT,transition_set TEXT NOT NULL CHECK(transition_set='holdings'),transition_old_id TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(transition_set,transition_old_id) REFERENCES context_rights_transition(set_name,old_id),CHECK(current_validity<>'current_seoul_nonowning' OR (kind='superior-jurisdiction' AND direct_ownership IS 0 AND title_id IS NOT NULL AND capability_package_id IS NOT NULL)),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_holding_admin_ref (holding_id TEXT NOT NULL REFERENCES context_holding(holding_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),admin_id TEXT NOT NULL,admin_name TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(holding_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_holding_reference (holding_id TEXT NOT NULL REFERENCES context_holding(holding_id),reference_kind TEXT NOT NULL CHECK(reference_kind IN ('station','facility','landmark')),ordinal INTEGER NOT NULL CHECK(ordinal>=0),reference_id TEXT,reference_name TEXT,reference_source_path TEXT,site_source_path TEXT,reference_anchor TEXT,station_id TEXT,station_name TEXT,station_district TEXT,station_lat REAL,station_lon REAL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(holding_id,reference_kind,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer),CHECK((station_lat IS NULL AND station_lon IS NULL) OR (station_lat BETWEEN -90 AND 90 AND station_lon BETWEEN -180 AND 180))) STRICT;
CREATE TABLE context_polity (polity_id TEXT PRIMARY KEY,name_ko TEXT NOT NULL,name_en TEXT,sovereign_person_id TEXT NOT NULL REFERENCES person(person_id),territorial_scale TEXT,formal_title TEXT NOT NULL,formal_title_rank TEXT NOT NULL,office TEXT NOT NULL,authority_kind TEXT NOT NULL,authority_name TEXT NOT NULL,current_validity TEXT NOT NULL CHECK(current_validity IN ('superseded_outside_seoul','current_nonterritorial')),source_schema TEXT NOT NULL,opening_year INTEGER NOT NULL,direct_ownership INTEGER CHECK(direct_ownership IN (0,1)),political_title_id TEXT REFERENCES context_feudal_title(title_id),approval_id TEXT REFERENCES context_rights_approval(approval_id),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_retinue_group (retinue_group_id TEXT PRIMARY KEY,name_ko TEXT NOT NULL,name_en TEXT,court_id TEXT NOT NULL REFERENCES context_court(court_id),liege_person_id TEXT NOT NULL REFERENCES person(person_id),person_count INTEGER NOT NULL CHECK(person_count>=0),personhood_review TEXT NOT NULL,formal_title TEXT,current_validity TEXT NOT NULL CHECK(current_validity IN ('superseded_outside_seoul','unresolved')),source_schema TEXT NOT NULL,opening_year INTEGER NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_retinue_duty (retinue_group_id TEXT NOT NULL REFERENCES context_retinue_group(retinue_group_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),duty TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(retinue_group_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_retinue_technical_limit (retinue_group_id TEXT NOT NULL REFERENCES context_retinue_group(retinue_group_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),technical_limit TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(retinue_group_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_retinue_holding (retinue_group_id TEXT NOT NULL REFERENCES context_retinue_group(retinue_group_id),holding_id TEXT NOT NULL REFERENCES context_holding(holding_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(retinue_group_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_opening_disposition (person_id TEXT PRIMARY KEY REFERENCES person(person_id),status TEXT NOT NULL,approval_ref TEXT NOT NULL,canon_status TEXT NOT NULL CHECK(canon_status='owner-approved'),authority_date TEXT,authority_ref TEXT NOT NULL,source_schema TEXT NOT NULL,opening_year INTEGER NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_office_appointment (person_id TEXT PRIMARY KEY REFERENCES person(person_id),polity_id TEXT NOT NULL,position_ko TEXT,position_en TEXT,rank_ko TEXT,rank_en TEXT,common_tier TEXT NOT NULL CHECK(common_tier GLOB 'T[1-5]'),status TEXT NOT NULL CHECK(status IN ('retained-office','unappointed','nonterritorial-political-office','nonowning-jurisdiction','existing-function')),source_schema TEXT NOT NULL,opening_year INTEGER NOT NULL,catalog_status TEXT NOT NULL CHECK(catalog_status='current-catalog-input'),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,CHECK(status<>'unappointed' OR (position_ko IS NULL AND position_en IS NULL AND rank_ko IS NULL AND rank_en IS NULL)),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE context_prose_contact (person_id TEXT NOT NULL REFERENCES person(person_id),recipient_person_id TEXT NOT NULL REFERENCES person(person_id),contact_kind TEXT NOT NULL,source_ref_path TEXT NOT NULL,source_ref_anchor TEXT NOT NULL,catalog_status TEXT NOT NULL CHECK(catalog_status='current-catalog-input'),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(person_id,recipient_person_id),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer),CHECK(person_id<>recipient_person_id)) STRICT;
CREATE TABLE context_issue (issue_id TEXT PRIMARY KEY,context_domain TEXT NOT NULL,code TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN ('warning','error')),holding_id TEXT REFERENCES context_holding(holding_id),person_id TEXT REFERENCES person(person_id),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,message TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE INDEX context_holding_current_idx ON context_holding(current_validity,holder_person_id);
CREATE INDEX context_office_polity_idx ON context_office_appointment(polity_id,common_tier);
CREATE INDEX context_contact_recipient_idx ON context_prose_contact(recipient_person_id);
